 <div id="dm_content" class="dmContent"> <div dm:templateorder="170" class="dmHomeRespTmpl mainBorder dmRespRowsWrapper dmFullRowRespTmpl" id="1716942098"> <div class="u_1325247579 dmRespRow mobile-columns-reversed dmSectionNoParallax" id="1325247579" data-blog-template="bind-bg-img"> <div class="dmRespColsWrapper" id="1462856210"> <div class="u_1287730679 dmRespCol small-12 medium-12 large-12" id="1287730679"> <h1 class="u_1852899778 dmNewParagraph" data-element-type="paragraph" id="1852899778" data-blog-template="bind-title" style="transition: none 0s ease 0s;" data-binding="W3siYmluZGluZ05hbWUiOiJ0ZXh0IiwidmFsdWUiOiJibG9nLnRpdGxlIn1d" data-diy-text="">Edital Chamamento P&uacute;blico para Organiza&ccedil;&atilde;o da Sociedade Civil (OSCS)</h1> <div class="u_1131577706 dmNewParagraph" data-element-type="paragraph" id="1131577706" data-blog-template="bind-author" style="transition: opacity 1s ease-in-out 0s; display: block;" data-binding="W3siYmluZGluZ05hbWUiOiJ0ZXh0IiwidmFsdWUiOiJibG9nLmRhdGUifV0=" data-diy-text="">13 de agosto de 2026</div></div> 
</div> 
